cat > /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/BlueskySearchUITest/BlueskySearchUITests/BlueskySearchUITests.swift <<'EOF'
import XCTest

final class BlueskySearchUITests: XCTestCase {
    func testSearchForCat() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 3) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let searchTab = app.coordinate(withNormalizedOffset: CGVector(dx: 0.306, dy: 0.914))
        searchTab.tap()

        let searchField = app.searchFields.firstMatch
        let textField = app.textFields.firstMatch
        let field = searchField.waitForExistence(timeout: 5) ? searchField : textField
        if field.waitForExistence(timeout: 5) {
            field.tap()
            if let value = field.value as? String, value != "cat" {
                let deleteCount = min(value.count, 30)
                field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: deleteCount))
            }
            field.typeText("cat")
            field.typeText("\n")
        }
        print("BLUESKY_UI_HIERARCHY_START\n\(app.debugDescription)\nBLUESKY_UI_HIERARCHY_END")
        sleep(5)
    }
}
EOF

